import os
import PyPDF2

TARGET_CITIZENSHIP = "United States"

def extract_names_from_resumes(resume_folder, output_file):
    with open(output_file, 'a') as out_file:
        for filename in os.listdir(resume_folder):
            if filename.endswith('.pdf'):
                file_path = os.path.join(resume_folder, filename)
                with open(file_path, 'rb') as file:
                    reader = PyPDF2.PdfReader(file)
                    text = ""
                    for page in reader.pages:
                        text += page.extract_text() or ""
                    if TARGET_CITIZENSHIP in text:
                        # Assuming the name is in the first line of the resume
                        name = text.split('\n')[0]
                        out_file.write(name + '\n')

if __name__ == '__main__':
    import sys
    if len(sys.argv) != 3:
        print("Usage: python resume_filter.py <resume_folder> <output_file>")
    else:
        extract_names_from_resumes(sys.argv[1], sys.argv[2])

